# nginx/conf.d/default.conf
server {
    listen 80;
    location / {
        proxy_pass http://tasks-api:8080;
        proxy_set_header Host $host;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
}

# compose.yaml
  proxy:
    image: nginx:1.27
    ports: ["80:80"]
    networks: [publiczna]
    volumes:
      - ./nginx/conf.d:/etc/nginx/conf.d:ro
    depends_on: [tasks-api]

Nginx i tasks-api są we wspólnej sieci publiczna, więc wbudowany DNS Dockera rozwiązuje nazwę serwisu tasks-api. Aplikacja Spring Boot powinna ufać nagłówkom z proxy (server.forward-headers-strategy=framework), żeby poprawnie budować adresy.
